    public static int lat(int[][] input, int[][] output, int[] sbox, int a, int b) {
        int count = 0;
        for (int x = 0; x < 8; x++) {
            // Convert input to an integer
            int inputInt = input[x][0] * 4 + input[x][1] * 2 + input[x][2];
            // Get the corresponding output from the S-box
