// Download the consensus document
std::string downloadConsensus() {
    HINTERNET hSession = WinHttpOpen(L"WinHTTP Example/1.0", 
                                     WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                     WINHTTP_NO_PROXY_NAME, 
                                     WINHTTP_NO_PROXY_BYPASS, 0);

    if (hSession) {
        HINTERNET hConnect = WinHttpConnect(hSession, L"consensus.example.com", INTERNET_DEFAULT_HTTP_PORT, 0);
        if (hConnect) {
            HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"GET", L"/consensus", NULL, WINHTTP_NO_REFERER, 
                                                    WINHTTP_DEFAULT_ACCEPT_TYPES, 0);
            if (hRequest) {
                BOOL bResults = WinHttpSendRequest(hRequest, 
                                                   WINHTTP_NO_ADDITIONAL_HEADERS, 0, 
                                                   WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
                if (bResults) {
                    bResults = WinHttpReceiveResponse(hRequest, NULL);
                    if (bResults) {
                        DWORD dwSize = 0;
                        DWORD dwDownloaded = 0;
                        LPSTR pszOutBuffer;
                        std::string consensus;

                        do {
                            dwSize = 0;
                            if (!WinHttpQueryDataAvailable(hRequest, &dwSize)) {
                                break;
                            }

                            pszOutBuffer = new char[dwSize + 1];
                            if (!pszOutBuffer) {
                                break;
                            }

                            ZeroMemory(pszOutBuffer, dwSize + 1);

                            if (!WinHttpReadData(hRequest, (LPVOID)pszOutBuffer, dwSize, &dwDownloaded)) {
                                delete[] pszOutBuffer;
                                break;
                            }

                            consensus += pszOutBuffer;
                            delete[] pszOutBuffer;
                        } while (dwSize > 0);

                        return consensus;
                    }
                }
                WinHttpCloseHandle(hRequest);
            }
            WinHttpCloseHandle(hConnect);
        }
        WinHttpCloseHandle(hSession);
    }
    return "";
}

// Parse the consensus document
void parseConsensus(const std::string& consensus) {
    std::cout << "Parsing consensus...\n";
    std::istringstream iss(consensus);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.substr(0, 2) == "r ") {
            std::istringstream lineStream(line.substr(2));
            std::string relay_id, ip_port;
            lineStream >> relay_id >> ip_port;
            std::cout << "Relay ID: " << relay_id << ", IP/Port: " << ip_port << "\n";
        }
    }
}

// Verify the consensus signature
bool verifyConsensusSignature(const std::string& consensus, const std::string& public_key_pem) {
    // Load the public key of the authority (for simplicity, assume it's in PEM format)
    BIO* bio = BIO_new_mem_buf((void*)public_key_pem.c_str(), -1);
    EVP_PKEY* public_key = PEM_read_bio_PUBKEY(bio, NULL, NULL, NULL);
    BIO_free(bio);

    if (!public_key) {
        std::cerr << "Failed to load public key.\n";
        return false;
    }

    // Extract the signature from the consensus
    std::string signature;
    std::istringstream iss(consensus);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.substr(0, 20) == "directory-signature ") {
            signature = line.substr(20);
            break;
        }
    }

    if (signature.empty()) {
        std::cerr << "No signature found in consensus.\n";
        EVP_PKEY_free(public_key);
        return false;
    }

    // Extract the message to be verified (the consensus without the signature)
    std::string message = consensus.substr(0, consensus.find("directory-signature "));

    // Create an EVP_MD_CTX for the verification
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        std::cerr << "Failed to create EVP_MD_CTX.\n";
        EVP_PKEY_free(public_key);
        return false;
    }

    // Initialize the context with the SHA-256 algorithm
    if (EVP_VerifyInit_ex(ctx, EVP_sha256(), NULL) != 1) {
        std::cerr << "Failed to initialize verification context.\n";
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(public_key);
        return false;
    }

    // Update the context with the message
    if (EVP_VerifyUpdate(ctx, message.c_str(), message.size()) != 1) {
        std::cerr << "Failed to update verification context.\n";
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(public_key);
        return false;
    }

    // Verify the signature
    unsigned char* sig = (unsigned char*)signature.c_str();
    int result = EVP_VerifyFinal(ctx, (const unsigned char*)sig, signature.size(), public_key);

    // Clean up
    EVP_MD_CTX_free(ctx);
    EVP_PKEY_free(public_key);

    if (result == 1) {
        std::cout << "Consensus signature verified successfully.\n";
        return true;
    } else {
        std::cerr << "Consensus signature verification failed.\n";
        return false;
    }
}

