HINTERNET establishConnection(const std::string& hiddenService, const std::string& introduction_point) {
    HINTERNET hSession = WinHttpOpen(L"WinHTTP Example/1.0", 
                                     WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                     WINHTTP_NO_PROXY_NAME, 
                                     WINHTTP_NO_PROXY_BYPASS, 0);

    if (hSession) {
        HINTERNET hConnect = WinHttpConnect(hSession, L"" + introduction_point, INTERNET_DEFAULT_HTTP_PORT, 0);
        if (hConnect) {
            return hConnect;
        }
        WinHttpCloseHandle(hSession);
    }
    return NULL;
}

// Send HTTP requests to the hidden service
void sendRequest(HINTERNET hConnect, const std::string& method, const std::string& url, const std::string& data = "") {
    HINTERNET hRequest = WinHttpOpenRequest(hConnect, method.c_str(), url.c_str(), NULL, WINHTTP_NO_REFERER, 
                                            WINHTTP_DEFAULT_ACCEPT_TYPES, 0);
    if (hRequest) {
        BOOL bResults = WinHttpSendRequest(hRequest, 
                                           WINHTTP_NO_ADDITIONAL_HEADERS, 0, 
                                           (LPVOID)data.c_str(), data.size(), data.size(), 0);
        if (bResults) {
            bResults = WinHttpReceiveResponse(hRequest, NULL);
            if (bResults) {
                DWORD dwSize = 0;
                DWORD dwDownloaded = 0;
                LPSTR pszOutBuffer;
                std::string response;

                do {
                    dwSize = 0;
                    if (!WinHttpQueryDataAvailable(hRequest, &dwSize)) {
                        break;
                    }

                    pszOutBuffer = new char[dwSize + 1];
                    if (!pszOutBuffer) {
                        break;
                    }

                    ZeroMemory(pszOutBuffer, dwSize + 1);

                    if (!WinHttpReadData(hRequest, (LPVOID)pszOutBuffer, dwSize, &dwDownloaded)) {
                        delete[] pszOutBuffer;
                        break;
                    }

                    response += pszOutBuffer;
                    delete[] pszOutBuffer;
                } while (dwSize > 0);

                std::cout << "Response: " << response << "\n";
            }
        }
        WinHttpCloseHandle(hRequest);
    }
}

